--! Minimal diffing, character-level inline patching, and buffer update utilities
--! with character-level accuracy for highlight-undo.nvim and single-step undo support.

local M = {}

--- Execute a callback while saving and restoring the current window view
---@generic T
---@param fn fun(): T
---@return T
function M.with_view(fn)
  local view = vim.fn.winsaveview()
  local ok, res = pcall(fn)
  vim.fn.winrestview(view)
  if not ok then
    error(res)
  end
  return res
end

--- Apply character-level inline diff to a single line using nvim_buf_set_text
--- Ensures only the exact changed characters/bytes are modified for highlight-undo.nvim
---@param bufnr integer
---@param row integer 0-indexed line number in buffer
---@param s1 string Old line content
---@param s2 string New line content
---@param opts? { join_undo?: boolean }|boolean
---@return boolean Whether any changes were applied
function M.apply_line_diff(bufnr, row, s1, s2, opts)
  if s1 == s2 then
    return false
  end

  local join_undo = type(opts) == "table" and opts.join_undo or (opts == true)

  local b1, b2 = {}, {}
  for i = 1, #s1 do
    table.insert(b1, s1:sub(i, i))
  end
  for i = 1, #s2 do
    table.insert(b2, s2:sub(i, i))
  end

  local t1 = table.concat(b1, "\n") .. "\n"
  local t2 = table.concat(b2, "\n") .. "\n"
  local hunks = vim.diff(t1, t2, { result_type = "indices" })
  if not hunks or #hunks == 0 then
    return false
  end

  -- Apply byte hunks in reverse order (right-to-left) so column offsets don't shift
  for i = #hunks, 1, -1 do
    local hunk = hunks[i]
    local start_a, count_a, start_b, count_b = hunk[1], hunk[2], hunk[3], hunk[4]
    local col_start = count_a > 0 and (start_a - 1) or start_a
    local col_end = col_start + count_a
    local replacement = count_b > 0 and s2:sub(start_b, start_b + count_b - 1) or ""

    if join_undo then
      pcall(vim.cmd.undojoin)
    end
    vim.api.nvim_buf_set_text(bufnr, row, col_start, row, col_end, { replacement })
  end

  return true
end

--- Apply minimal diff edits to buffer to update only the lines/characters that changed
--- Uses vim.diff to calculate exact hunks, preserving untouched lines and characters for highlight-undo.nvim
---@param bufnr integer
---@param base_line integer 0-indexed start line of block in buffer
---@param old_lines string[]
---@param new_lines string[]
---@param opts? { join_undo?: boolean, char_diff?: boolean, save_view?: boolean }|boolean
---@return boolean Whether any edits were applied
function M.apply_diff(bufnr, base_line, old_lines, new_lines, opts)
  local join_undo = type(opts) == "table" and opts.join_undo or (opts == true)
  local char_diff = type(opts) ~= "table" or opts.char_diff ~= false
  local save_view = type(opts) == "table" and opts.save_view

  local function apply_fn()
    local old_text = table.concat(old_lines, "\n") .. "\n"
    local new_text = table.concat(new_lines, "\n") .. "\n"

    local hunks = vim.diff(old_text, new_text, { result_type = "indices" })
    if not hunks or #hunks == 0 then
      return false
    end

    -- Apply hunks in reverse order (bottom-to-top) so earlier line indices remain stable
    for i = #hunks, 1, -1 do
      local hunk = hunks[i]
      local start_a, count_a, start_b, count_b = hunk[1], hunk[2], hunk[3], hunk[4]

      local buf_start, buf_end
      if count_a > 0 then
        buf_start = base_line + start_a - 1
        buf_end = buf_start + count_a
      else
        buf_start = base_line + start_a
        buf_end = buf_start
      end

      if count_a == count_b and count_a > 0 and char_diff then
        -- Same number of lines modified: apply character-level inline diff per line
        for line_offset = count_a - 1, 0, -1 do
          local r = buf_start + line_offset
          local s1 = old_lines[start_a + line_offset]
          local s2 = new_lines[start_b + line_offset]
          M.apply_line_diff(bufnr, r, s1, s2, { join_undo = join_undo })
        end
      else
        -- Lines were added or deleted: replace the line hunk
        local replacement = {}
        if count_b > 0 then
          for k = start_b, start_b + count_b - 1 do
            table.insert(replacement, new_lines[k])
          end
        end

        if join_undo then
          pcall(vim.cmd.undojoin)
        end
        vim.api.nvim_buf_set_lines(bufnr, buf_start, buf_end, false, replacement)
      end
    end

    return true
  end

  if save_view then
    return M.with_view(apply_fn)
  else
    return apply_fn()
  end
end

--- Replace a line range in buffer with new lines
---@param bufnr integer
---@param start_line integer 0-indexed start line
---@param end_line integer 0-indexed end line (exclusive)
---@param lines string[] Replacement lines
---@param opts? { join_undo?: boolean, save_view?: boolean }|boolean
function M.replace_lines(bufnr, start_line, end_line, lines, opts)
  local join_undo = type(opts) == "table" and opts.join_undo or (opts == true)
  local save_view = type(opts) == "table" and opts.save_view

  local function replace_fn()
    if join_undo then
      pcall(vim.cmd.undojoin)
    end
    vim.api.nvim_buf_set_lines(bufnr, start_line, end_line, false, lines)
  end

  if save_view then
    M.with_view(replace_fn)
  else
    replace_fn()
  end
end

--- Insert lines into buffer at a given row
---@param bufnr integer
---@param row integer 0-indexed line number
---@param lines string[] Lines to insert
---@param opts? { join_undo?: boolean, save_view?: boolean }|boolean
function M.insert_lines(bufnr, row, lines, opts)
  M.replace_lines(bufnr, row, row, lines, opts)
end

return M
